function reviewDockerfile(text, scripts = {}) {
  // Write your solution here
  const found = [];
  if (/FROM node:\d+(\s|$)/.test(text)) found.push('UNPINNED_TAG');
  if (/CMD \["npm"/.test(text)) found.push('NOT_EXEC_PID1');
  if (!/USER /.test(text)) found.push('ROOT_USER');
  return found;
}

